export type Guide = (typeof GUIDES)[number];

export const card = (page: Page, g: Guide) => page.getByRole('article', { name: g.title });
export const videoOf = (page: Page, g: Guide) => page.getByLabel(`סרטון: ${g.title}`);

export async function openGuides(page: Page) {
  // #359741: страница под admin; роль приходит из GET rest/v1/app_user — после ответа список перерисовывается,
  // поэтому карточки считаем после него (иначе плеер может открепиться от DOM посреди действия).
  const role = page.waitForResponse((r) => r.request().method() === 'GET' && /\/rest\/v1\/app_user\?/.test(r.url()), LOAD);
  await page.goto('/guides');
  await role;
  await expect(page.getByRole('article')).toHaveCount(GUIDES.length, LOAD);
}

/** Шаг без номера: номер — отдельный <span> внутри <li>, берём только текстовые узлы. */
export const stepTexts = (scope: Locator) =>
  scope.getByRole('listitem').evaluateAll((els) =>
    els.map((li) => [...li.childNodes].filter((n) => n.nodeType === Node.TEXT_NODE).map((n) => n.textContent).join('').trim()),
  );

export type VideoState = { paused: boolean; currentTime: number; muted: boolean; volume: number; error: number | null };
export const videoState = (video: Locator) =>
  video.evaluate((v: HTMLVideoElement): VideoState => ({
    paused: v.paused, currentTime: v.currentTime, muted: v.muted, volume: v.volume, error: v.error ? v.error.code : null,
  }));

/** Ответ /guides/<id>.mp4 — подписаться ДО нажатия. */
export const mp4Response = (page: Page, g: Guide) =>
  page.waitForResponse((r) => new URL(r.url()).pathname === `/guides/${g.id}.mp4`, LOAD);

/** Дождаться, что видео идёт: currentTime > sec (без пауз — опрос состояния). */
export async function expectPlaying(video: Locator, sec: number, what: string) {
  await expect
    .poll(async () => (await videoState(video)).currentTime, { message: `${what}: currentTime > ${sec} с`, ...LOAD })
    .toBeGreaterThan(sec);
}

/** Проверки «играет со звуком» из плана (1.3/1.4): mp4 200/206 video/mp4, не на паузе, не muted, громкость > 0, без ошибки. */
export async function expectPlaysWithSound(video: Locator, resp: Awaited<ReturnType<typeof mp4Response>>, g: Guide) {
  expect([200, 206], `статус /guides/${g.id}.mp4`).toContain(resp.status());
  expect(resp.headers()['content-type'] ?? '', `content-type /guides/${g.id}.mp4`).toContain('video/mp4');
  const s = await videoState(video);
  expect(s.paused, `${g.id}: видео не на паузе`).toBe(false);
  expect(s.muted, `${g.id}: звук не выключен (muted)`).toBe(false);
  expect(s.volume, `${g.id}: громкость`).toBeGreaterThan(0);
  expect(s.error, `${g.id}: video.error`).toBeNull();
}

/**
 * Десктоп: запуск встроенного плеера с клавиатуры — фокус на видео и «Пробел».
 * Клик по центру плеера в headless Chromium воспроизведение не запускает (проверено 2026-11-03, playwright-cli),
 * «Пробел» на видео с controls — штатное управление плеером пользователем.
 */
export async function startDesktop(page: Page, video: Locator) {
  await video.scrollIntoViewIfNeeded();
  await video.focus();
  await page.keyboard.press('Space');
}

export async function stop(video: Locator) {
  await video.evaluate((v: HTMLVideoElement) => v.pause());
  await expect.poll(async () => (await videoState(video)).paused).toBe(true);
}

