export const GUIDES_LINKS = 'a[href*="guides" i]';

/** Варианты прямого адреса, которые не-админ не должен видеть (/GUIDES и /guides/ — 301 на /guides). */
export const DIRECT_GUIDES_URLS = ['/guides', '/guides/', '/GUIDES', '/guides?x=1'] as const;

/** Попапы, мешающие меню: окно PWA — «אולי מאוחר יותר», cookie — «חיוניים בלבד» (если показан). */
export async function dismissPopups(page: Page) {
  await page.addLocatorHandler(page.getByRole('button', { name: 'אולי מאוחר יותר' }), (b) => b.click());
  await page.addLocatorHandler(page.getByRole('button', { name: 'חיוניים בלבד' }), (b) => b.click());
}

/** Мобильное меню «תפריט» (Radix Sheet). Кнопку ищем только exact — есть ещё «פתח תפריט נגישות». */
export async function openMobileMenu(page: Page) {
  const button = page.getByRole('banner').getByRole('button', { name: 'תפריט', exact: true }).filter({ visible: true });
  await expect(button, 'одна видимая кнопка «תפריט» в шапке').toHaveCount(1, LOAD);
  await button.click();
  const menu = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: 'תפריט', exact: true }) });
  await expect(menu, 'меню «תפריט» открыто').toBeVisible(LOAD);
  await expect(menu.getByRole('link', { name: 'דף הבית', exact: true }), 'пункты меню отрисованы').toBeVisible(LOAD);
  return menu;
}

/** Страница гайдов не показана: нет h1 «מדריכי וידאו», карточек и видео /guides/*.mp4. */
export async function expectNoGuidesContent(page: Page, where: string) {
  await expect(page.getByRole('heading', { name: 'מדריכי וידאו' }), `${where}: заголовка «מדריכי וידאו» нет`).toHaveCount(0);
  await expect(page.locator('video[src*="/guides/"], video source[src*="/guides/"]'), `${where}: видео гайдов нет`).toHaveCount(0);
  for (const g of GUIDES) await expect(page.getByLabel(`סרטון: ${g.title}`), `${where}: плеера «${g.title}» нет`).toHaveCount(0);
}

/** Тексты видимых ссылок области (по порядку DOM). */
export const linkTexts = async (scope: Locator) => (await scope.getByRole('link').allInnerTexts()).map((t) => t.trim());

/** Порядок «a → b» в списке ссылок: сразу за a идёт b. */
export function expectNext(texts: string[], a: string, b: string, where: string) {
  const i = texts.indexOf(a);
  expect(i, `${where}: есть «${a}» (ссылки: ${texts.join(' · ')})`).toBeGreaterThanOrEqual(0);
  expect(texts[i + 1], `${where}: сразу после «${a}» (ссылки: ${texts.join(' · ')})`).toBe(b);
}

